    "code": "        use crate::NurbsCurve;\n        use crate::Point;\n        use crate::Primitives;\n        use crate::Vector;\n\n        let pa = NurbsCurve::create(\n            false,\n            3,\n            &[\n                Point::new(1.5, 0.0, 0.0),\n                Point::new(1.5, 0.0, 0.3),\n                Point::new(0.3, 0.0, 0.5),\n                Point::new(0.3, 0.0, 2.5),\n                Point::new(0.2, 0.0, 3.0),\n                Point::new(2.0, 0.0, 4.5),\n                Point::new(1.8, 0.0, 5.0),\n            ],\n        );\n        let s_vase = Primitives::create_revolve(\n            &pa,\n            &Point::new(0.0, 0.0, 0.0),\n            &Vector::new(0.0, 0.0, 1.0),\n            2.0 * PI,\n        );\n        let m_vase = s_vase.mesh();\n\n        let w = (2.0_f64).sqrt() / 2.0;\n        let cw = [1.0, w, 1.0, w, 1.0, w, 1.0, w, 1.0];\n        let ca = [1.0, 1.0, 0.0, -1.0, -1.0, -1.0, 0.0, 1.0, 1.0];\n        let sa = [0.0, 1.0, 1.0, 1.0, 0.0, -1.0, -1.0, -1.0, 0.0];\n        let ck = [0.0, 0.0, 1.0, 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 4.0];\n        let rr = 5.0;\n        let r = 1.5;\n        let tcx = 14.0;\n        let mut pb = NurbsCurve::new(3, true, 3, 9);\n        for i in 0..10 {\n            pb.set_nurbsknot(i, ck[i]);\n        }\n        for i in 0..9 {\n            pb.set_cv_4d(\n                i,\n                (tcx + rr + r * ca[i]) * cw[i],\n                0.0,\n                r * sa[i] * cw[i],\n                cw[i],\n            );\n        }\n        let s_torus = Primitives::create_revolve(\n            &pb,\n            &Point::new(tcx, 0.0, 0.0),\n            &Vector::new(0.0, 0.0, 1.0),\n            2.0 * PI,\n        );\n        let m_torus = s_torus.mesh();\n\n        let pc = NurbsCurve::create(\n            false,\n            1,\n            &[Point::new(29.0, 0.0, -0.5), Point::new(29.0, 0.0, 0.5)],\n        );\n        let s_elbow = Primitives::create_revolve(\n            &pc,\n            &Point::new(26.0, 0.0, 0.0),\n            &Vector::new(0.0, 0.0, 1.0),\n            PI / 2.0,\n        );\n        let m_elbow = s_elbow.mesh();\n\n        let sr = 2.0;\n        let scx = 36.0;\n        let mut pd = NurbsCurve::new(3, true, 3, 5);\n        let sk = [0.0, 0.0, 1.0, 1.0, 2.0, 2.0];\n        for i in 0..6 {\n            pd.set_nurbsknot(i, sk[i]);\n        }\n        let spx = [0.0, sr, sr, sr, 0.0];\n        let spz = [-sr, -sr, 0.0, sr, sr];\n        let spw = [1.0, w, 1.0, w, 1.0];\n        for i in 0..5 {\n            pd.set_cv_4d(i, (scx + spx[i]) * spw[i], 0.0, spz[i] * spw[i], spw[i]);\n        }\n        let s_sphere = Primitives::create_revolve(\n            &pd,\n            &Point::new(scx, 0.0, 0.0),\n            &Vector::new(0.0, 0.0, 1.0),\n            2.0 * PI,\n        );\n        let m_sphere = s_sphere.mesh();\n\n        let pe = NurbsCurve::create(\n            false,\n            1,\n            &[Point::new(44.0, 0.0, 3.0), Point::new(46.0, 0.0, 0.0)],\n        );\n        let s_cone = Primitives::create_revolve(\n            &pe,\n            &Point::new(44.0, 0.0, 0.0),\n            &Vector::new(0.0, 0.0, 1.0),\n            2.0 * PI,\n        );\n        let m_cone = s_cone.mesh();\n\n",
